<?php require 'config.php';$title='Roadmap — FeatureBoard';require 'header.php';$rows=db()->query("SELECT * FROM features WHERE status IN ('under_review','planned','in_progress','shipped') ORDER BY votes DESC")->fetchAll();$cols=['under_review'=>'Under review','planned'=>'Planned','in_progress'=>'In progress','shipped'=>'Shipped'];?>
<section class="page"><div class="wrap"><div class="eyebrow">Public roadmap</div><h1 style="font-family:'Space Grotesk';font-size:52px;margin:12px 0">Where ideas go next.</h1><p style="color:var(--muted);font-size:17px;max-width:650px">A transparent view of what the community has asked for and what the team is actively building.</p><div style="display:grid;grid-template-columns:repeat(4,minmax(230px,1fr));gap:14px;margin-top:35px;overflow:auto"><?php foreach($cols as $key=>$label):?><div class="panel roadcols"><div class="status <?=e($key)?>" style="display:inline-block"><?=e($label)?></div><div style="display:grid;gap:10px;margin-top:15px"><?php foreach($rows as $f): if($f['status']===$key):?><a class="panel" style="padding:15px;border-radius:13px" href="feature.php?slug=<?=urlencode($f['slug'])?>"><b><?=e($f['title'])?></b><div style="color:var(--muted);font-size:12px;margin-top:7px">▲ <?=$f['votes']?> votes</div></a><?php endif; endforeach;?></div></div><?php endforeach;?></div></div></section><?php require 'footer.php';?>
